import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const e="/img/math-vertical-calc.svg",g=JSON.parse('{"title":"基础突破：加减竖式的规范与进退位奥秘","description":"竖式是计算大数字最有效的工具。如何写出规范的竖式？进位和退位时怎么保证不出错？本文手把手教你掌握竖式计算的精髓。","frontmatter":{"title":"基础突破：加减竖式的规范与进退位奥秘","date":"2026-02-12T09:00:00.000Z","categories":["杂谈"],"tags":["小学数学","竖式计算","进位加法","退位减法"],"description":"竖式是计算大数字最有效的工具。如何写出规范的竖式？进位和退位时怎么保证不出错？本文手把手教你掌握竖式计算的精髓。","cover":"/img/math-vertical-calc.svg","top_img":"/img/math-vertical-calc.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-vertical-calc.md","filePath":"posts/primary-math-vertical-calc.md","lastUpdated":null}'),l={name:"posts/primary-math-vertical-calc.md"};function p(r,a,o,i,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="基础突破-加减竖式的规范与进退位奥秘" tabindex="-1">基础突破：加减竖式的规范与进退位奥秘 <a class="header-anchor" href="#基础突破-加减竖式的规范与进退位奥秘" aria-label="Permalink to &quot;基础突破：加减竖式的规范与进退位奥秘&quot;">​</a></h1><p>当数字变大，口算就不够用了。这时候，我们需要请出数学里的“排队大师”——<strong>竖式</strong>。</p><p>竖式计算虽然看起来死板，但它有一套极其严谨的规则。只要守住这些规则，再大的数你也难不倒你。</p><hr><h2 id="一、-竖式的三大基本原则" tabindex="-1">一、 竖式的三大基本原则 <a class="header-anchor" href="#一、-竖式的三大基本原则" aria-label="Permalink to &quot;一、 竖式的三大基本原则&quot;">​</a></h2><ol><li><strong>相同数位对齐</strong>：个位对个位，十位对十位。这是基础中的基础！</li><li><strong>从个位算起</strong>：永远先处理最右边的数字。</li><li><strong>符号写在左下</strong>：让加号或减号待在它该在的位置。</li></ol><hr><h2 id="二、-进位加法-满十进一" tabindex="-1">二、 进位加法：满十进一 <a class="header-anchor" href="#二、-进位加法-满十进一" aria-label="Permalink to &quot;二、 进位加法：满十进一&quot;">​</a></h2><p>当某一位相加的结果达到或超过 10 时，就需要向它的左边邻居“借个位子”。</p><p><img src="'+e+'" alt="加法竖式进位示意图"></p><p><strong>【操作流程】</strong>：</p><ul><li>个位 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>+</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">8 + 5 = 13</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">3</span></span></span></span>。</li><li>把 3 写在个位，把 1 悄悄写在十位的左下方（或头顶）。</li><li>算十位时：4 + 3 + 1(\\text{进位的}) = 8。</li><li>结果：83。</li></ul><hr><h2 id="三、-退位减法-借一当十" tabindex="-1">三、 退位减法：借一当十 <a class="header-anchor" href="#三、-退位减法-借一当十" aria-label="Permalink to &quot;三、 退位减法：借一当十&quot;">​</a></h2><p>当上面的数字不够减时，就需要向左边的邻居“借钱”。</p><p><strong>【操作流程】</strong>：</p><ul><li>例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mn>2</mn><mo>−</mo><mn>2</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">52 - 27</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span></span></span></span>。</li><li>个位 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>−</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">2 - 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">7</span></span></span></span> 不够减，向十位借 1。</li><li>2 变成了 12，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>−</mo><mn>7</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">12 - 7 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span>。</li><li>十位 5 被借走了 1，变成了 4，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">4 - 2 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span>。</li><li>结果：25。</li></ul><hr><h2 id="四、-避坑指南-消失的-借位点-和-进位符" tabindex="-1">四、 避坑指南：消失的“借位点”和“进位符” <a class="header-anchor" href="#四、-避坑指南-消失的-借位点-和-进位符" aria-label="Permalink to &quot;四、 避坑指南：消失的“借位点”和“进位符”&quot;">​</a></h2><p>很多小朋友出错，是因为忘了算进上去的那位，或者忘了十位已经借出去一位了。</p><ul><li><strong>好习惯</strong>：进位时一定要写下那个小小的“1”，退位时一定要在十位上打个小点（·）。</li></ul><hr><h2 id="五、-练一练-竖式大挑战" tabindex="-1">五、 练一练（竖式大挑战） <a class="header-anchor" href="#五、-练一练-竖式大挑战" aria-label="Permalink to &quot;五、 练一练（竖式大挑战）&quot;">​</a></h2><ol><li><strong>加法题</strong>：用竖式计算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>6</mn><mo>+</mo><mn>4</mn><mn>7</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">36 + 47 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span></li><li><strong>减法题</strong>：用竖式计算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mn>0</mn><mo>−</mo><mn>3</mn><mn>4</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">80 - 34 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span></li><li><strong>纠错题</strong>：明明算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>5</mn><mo>+</mo><mn>1</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">45 + 18</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">8</span></span></span></span> 时，个位写了 3，十位写了 5，他错在哪了？</li></ol><hr><p><em>总结：竖式计算是数学的基本功。对齐、细心、标记，只要做到这六个字，你就是计算小能手！</em></p>',26)])])}const u=s(l,[["render",p]]);export{g as __pageData,u as default};
